// src/services/authentication.ts
import { LocalStorageService } from '@/storages/local_storage_service';
import { URLS, USE_SEED_DATA } from '../config';
import * as seed from '@/seeders/api';

type AuthResponse = {
  etat: boolean;
  message?: string;
  error?: string[];
  result?: any; // Remplacez par votre type User si disponible
};

export async function requestAuthentication(
  phoneNumber: string,
): Promise<AuthResponse> {
  if (USE_SEED_DATA) return seed.requestAuthentication(phoneNumber);

  try {
    const origin = globalThis.origin;
    const response = await fetch(URLS.AUTHENTICATION, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Origin: origin,
      },
      body: JSON.stringify({ phone_number: phoneNumber }),
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(
        errorData.message || "Échec de la demande d'authentification",
      );
    }

    return await response.json();
  } catch (error) {
    console.error('Error in requestAuthentication:', error);
    throw error; // À gérer dans le composant appelant
  }
}

export async function verifyAuthentication(
  phoneNumber: string,
  otp: string,
): Promise<AuthResponse> {
  if (USE_SEED_DATA) return seed.verifyAuthentication(phoneNumber, otp);

  try {
    const origin = globalThis.origin;
    const response = await fetch(URLS.VERIFY_AUTHENTICATION, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Origin: origin,
      },
      body: JSON.stringify({
        phone_number: phoneNumber,
        otp: otp,
      }),
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.message || 'Échec de la vérification OTP');
    }

    const data = (await response.json()) as AuthResponse;

    // Stockage du token si présent dans la réponse
    if (data.etat && typeof window !== 'undefined') {
      const { access_token, ...rest } = data.result.client;
      LocalStorageService.saveToken(access_token);
      data.result.client = rest;
    }

    return data;
  } catch (error) {
    console.error('Error in verifyAuthentication:', error);
    throw error; // À gérer dans le composant appelant
  }
}

export async function createAnonymousUser(): Promise<AuthResponse> {
  if (USE_SEED_DATA) return seed.createAnonymousUser();

  try {
    const origin = window.origin;
    const response = await fetch(URLS.ANONYMOUS_USER, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Origin: origin,
      },
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.message || 'Échec de la vérification OTP');
    }

    const data = (await response.json()) as AuthResponse;

    // Stockage du token si présent dans la réponse
    if (data.etat && typeof window !== 'undefined') {
      const { access_token, ...rest } = data.result.client;
      LocalStorageService.saveToken(access_token);
      LocalStorageService.saveUser(rest);
      data.result.client = rest;
    }

    return data;
  } catch (error) {
    console.error('Error in verifyAuthentication:', error);
    throw error; // À gérer dans le composant appelant
  }
}
