'use client';

import React, { useRef } from 'react';
import Link from 'next/link';
import Image from 'next/image';

import type { Game } from '../types';

import { Routes } from '../routes';
import { Button } from '@/components/Button';
import { URLS_ASSETS } from '@/config';
import { stores } from '@/stores';
import { useRouter } from 'next/navigation';
import { svg } from '@/svg';
import { LocalStorageService } from '@/storages/local_storage_service';
import { GamePreloadService } from '@/services/GamePreloadService';
import { useGamePreload } from '@/hooks/useGamePreloader';
import { UserType } from '@/types/UserType';
import { hasActiveSubscription } from '@/utils/subscription_helper';

type Props = {
  isLast?: boolean;
  game: Game;
  border?: boolean;
  enablePreload?: boolean;
};

export const GameItemRow: React.FC<Props> = ({
  game,
  isLast,
  border = false,
  enablePreload = true,
}) => {
  const router = useRouter();
  const { openModal: openModalSubscribe } = stores.useModalSubscribe();
  const containerRef = useRef<HTMLLIElement>(null);
  const { user } = stores.useUserStore();
  // Hook de préchargement
  const { handleMouseEnter, handleMouseLeave, status } = useGamePreload(
    game,
    containerRef,
    {
      enabled: enablePreload,
      enableHover: true,
      enableVisibility: true,
      hoverDelay: 150, // Plus rapide pour les lignes car intention plus claire
      visibilityThreshold: 0.5, // Threshold plus élevé pour les lignes
      visibilityRootMargin: '50px',
    },
  );

  const handlePlayClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();

    const url = `${Routes.GAME_PLAY}/${game?.title.replaceAll(' ', '_')}/${game?.id}`;

    if (user && hasActiveSubscription(user.subscriptions)) {
      // console.log(`🎯 Clic sur "${game.title}" - Statut: ${status}`);

      if (status === 'loaded') {
        // console.log(`⚡ Chargement instantané du jeu préchargé!`);
      } else if (status === 'loading') {
        // console.log(`⏳ Jeu en cours de préchargement...`);
      } else {
        // console.log(`🔄 Chargement normal du jeu`);
      }

      router.push(url);
      return;
    }

    LocalStorageService.saveLocationRedirection(url);
    openModalSubscribe();
  };

  return (
    <li
      ref={containerRef}
      className="game-item-row"
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      style={{
        position: 'relative',
        height: 100,
        padding: 10,
        outline: 'none',
        backgroundColor: 'var(--white-color)',
        border: border
          ? '2px solid var(--accent-color)'
          : '2px solid transparent',
        transition: 'border-color 0.3s ease',
        borderRadius: 20,
        display: 'flex',
        alignItems: 'center',
        flexDirection: 'row',
        marginBottom: isLast ? 0 : 10,
      }}
    >
      <Link
        href={`${Routes.GAME}/${game.title.replaceAll(' ', '_')}/${game.id}`}
        style={{ position: 'relative', marginRight: 14 }}
      >
        <Image
          src={`${URLS_ASSETS.GAMES}/${game.profilPicture}`}
          alt={game.title}
          width={80}
          height={80}
          style={{ borderRadius: 12, objectFit: 'cover' }}
        />
      </Link>

      <div
        onClick={(e) => {
          e.stopPropagation();
          e.preventDefault();
          router.push(
            `${Routes.GAME}/${game.title.replaceAll(' ', '_')}/${game.id}`,
          );
        }}
        style={{
          marginRight: 'auto',
          display: 'flex',
          flexDirection: 'column',
          height: '100%',
          justifyContent: 'space-between',
        }}
      >
        <h6>{game.title}</h6>
      </div>

      <div
        onClick={(e) => {
          e.stopPropagation();
          e.preventDefault();
          router.push(
            `${Routes.GAME}/${game.title.replaceAll(' ', '_')}/${game.id}`,
          );
        }}
        style={{
          display: 'flex',
          flexDirection: 'column',
          height: '100%',
          justifyContent: 'space-between',
          alignItems: 'center',
        }}
      >
        <button
          title="favoris"
          style={{
            position: 'absolute',
            top: 16 - 10,
            right: 18 - 10,
            borderRadius: '50%',
          }}
          onClick={(e) => {
            e.stopPropagation();
            e.preventDefault();
          }}
        >
          <svg.HeartSvg />
        </button>

        <Button
          label="Jouer"
          containerStyle={{
            position: 'absolute',
            bottom: 10,
            right: 10,
            width: '40%',
          }}
          style={{ padding: 0, margin: 0, height: 30 }}
          onClick={handlePlayClick}
        />
      </div>
    </li>
  );
};
