'use client';

import React, { useEffect } from 'react';
import { useRouter } from 'next/navigation';

import { stores } from '../stores';
import { TabScreens, Routes } from '../routes';
import { Box } from '@mui/material';
import { HomeTabSvg } from '@/svg/tabs/HomeTabSvg';
import { SearchTabSvg } from '@/svg/tabs/SearchTabSvg';
import { ProfileTabSvg } from '@/svg/tabs/ProfileTabSvg';

type Props = {
  currentActive: number;
  onChange: (value: number) => void;
};

export const BottomTabBar: React.FC<Props> = ({ onChange, currentActive }) => {
  const router = useRouter();
  const { isLoggedIn, initAuth, isLoadedCurrentUser } = stores.useUserStore();

  const tabs = [
    {
      id: TabScreens.HOME,
      name: TabScreens.HOME,
      icon: <HomeTabSvg active={currentActive === 0} />,
      route: Routes.HOME,
    },
    {
      id: TabScreens.CATEGORIES,
      name: TabScreens.CATEGORIES,
      icon: <SearchTabSvg active={currentActive === 1} />,
      route: Routes.CATEGORIES,
    },

    {
      id: TabScreens.PROFILE,
      name: TabScreens.PROFILE,
      icon: <ProfileTabSvg active={currentActive === 2} />,
      route: Routes.PROFILE,
    },
  ];

  useEffect(() => {
    initAuth();
  }, [initAuth, isLoggedIn]);

  // console.log(pathname, 'pathname');

  return (
    <section>
      <nav
        style={{
          paddingLeft: '3%',
          paddingRight: '3%',
          borderTop: '1px solid #C8CDD9',
          backgroundColor: '#F5FAFB',
        }}
      >
        <ul
          style={{
            display: 'grid',
            gridTemplateColumns: `repeat(${tabs.length}, 1fr)`,
          }}
        >
          {tabs.map((tab, index) => {
            return (
              <li
                key={tab.id}
                style={{
                  display: 'flex',
                  justifyContent: 'center',
                  alignItems: 'center',
                  flexDirection: 'column',
                }}
              >
                <Box
                  id={tab.id}
                  onClick={() => {
                    if (
                      tab.name === TabScreens.PROFILE &&
                      !isLoggedIn &&
                      isLoadedCurrentUser
                    ) {
                      router.push(Routes.SIGN_IN);
                      return;
                    }
                    onChange(index);
                  }}
                  style={{
                    width: '100%',
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    paddingTop: 15,
                    paddingBottom: 15,
                    borderRadius: 20,
                  }}
                >
                  {tab.icon}
                  <span
                    style={{
                      fontSize: 10,
                      marginTop: 3,
                      display: 'block',
                      color:
                        currentActive === index
                          ? 'var(--main-color)'
                          : 'var(--text-color)',
                      textTransform: 'uppercase',
                      textAlign: 'center',
                      fontWeight: 500,
                      lineHeight: 1.5,
                      fontFamily: 'var(--font-league-spartan)',
                    }}
                    className="number-of-lines-1"
                  >
                    {tab.name}
                  </span>
                </Box>
              </li>
            );
          })}
        </ul>
      </nav>
    </section>
  );
};
