'use client';

import Image from 'next/image';
import React, { useEffect, useRef, useState } from 'react';
import { Swiper, SwiperSlide } from 'swiper/react';
import { Swiper as SwiperClass } from 'swiper';
import { Navigation } from 'swiper/modules';

import ReviewsTwoToneIcon from '@mui/icons-material/ReviewsTwoTone';
import MilitaryTechTwoToneIcon from '@mui/icons-material/MilitaryTechTwoTone';

import { svg } from '../../../svg';
import { items } from '../../../items';
import { Routes } from '../../../routes';
import { components } from '../../../components';

import type { Game, ReviewType } from '../../../types';
import YouTubePlayer from '@/components/player/video/youtube/YoutubePlayer';
import {
  Box,
  CircularProgress,
  Stack,
  Tab,
  Tabs,
  useTheme,
} from '@mui/material';
import { URLS_ASSETS } from '@/config';
import { useDeviceDetect } from '@/hooks/useDeviceDetect';
import { Button } from '@/components/Button';
import { useRouter } from 'next/navigation';
import { stores } from '@/stores';
import { Avatar, Badge } from 'antd';
import { NoGammers } from '@/components/NoGammer';
import { LocalStorageService } from '@/storages/local_storage_service';
import { UserType } from '@/types/UserType';
import { hasActiveSubscription } from '@/utils/subscription_helper';

type Props = {
  reviews: ReviewType[];
  game: Game | null;
  ranking: {
    myRank: RankingType | null;
    allRanking: RankingType[];
  };
  isLoading: boolean;
};

export const GameContent: React.FC<Props> = ({
  game,
  reviews,
  ranking,
  isLoading,
}) => {
  const { isDesktop } = useDeviceDetect();
  const theme = useTheme();
  const router = useRouter();
  const { openModal: openModalSubscribe } = stores.useModalSubscribe();

  const activeColor = theme.palette.primary.main;
  const inactiveColor = theme.palette.action.active;

  const swiperInstanceRef = useRef<SwiperClass | null>(null);

  const [activeTab, setActiveTab] = useState<number>(0);
  const prevRef = useRef<HTMLDivElement>(null);
  const nextRef = useRef<HTMLDivElement>(null);

  const [isBeginning, setIsBeginning] = useState<boolean>(true);
  const [isEnd, setIsEnd] = useState<boolean>(false);
  const { user } = stores.useUserStore();

  // Effect pour calculer les états isEnd
  useEffect(() => {
    if (!game) return;

    const coversLength = game.covers.length || 0;

    if (
      (coversLength <= 5 && isDesktop && game.isPortrait) ||
      (coversLength <= 2 && !isDesktop && game.isPortrait) ||
      (coversLength <= 3 && !game.isPortrait && isDesktop) ||
      (coversLength <= 1 && !game.isPortrait && !isDesktop)
    ) {
      setIsEnd(true);
    } else {
      setIsEnd(false);
    }
  }, [game, isDesktop]);

  // Effect pour initialiser la navigation après le rendu
  useEffect(() => {
    const timer = setTimeout(() => {
      if (
        swiperInstanceRef.current &&
        !swiperInstanceRef.current.destroyed &&
        prevRef.current &&
        nextRef.current
      ) {
        const swiper = swiperInstanceRef.current;

        // Détruire l'ancienne navigation
        if (swiper.navigation) {
          swiper.navigation.destroy();
        }

        // Reconfigurer la navigation (merge pour ne pas écraser les classes
        // par défaut de Swiper comme disabledClass, sinon le prochain
        // navigation.destroy() plante sur `disabledClass.split is not a function`)
        if (
          typeof swiper.params.navigation === 'object' &&
          swiper.params.navigation
        ) {
          Object.assign(swiper.params.navigation, {
            prevEl: prevRef.current,
            nextEl: nextRef.current,
          });
        }

        // Réinitialiser la navigation
        swiper.navigation.init();
        swiper.navigation.update();
      }
    }, 100); // Petit délai pour s'assurer que les éléments sont dans le DOM

    return () => clearTimeout(timer);
  }, [game, isDesktop]);

  // Fonctions de navigation manuelles en cas de problème
  const handlePrevSlide = () => {
    if (swiperInstanceRef.current && !swiperInstanceRef.current.destroyed) {
      swiperInstanceRef.current.slidePrev();
    }
  };

  const handleNextSlide = () => {
    if (swiperInstanceRef.current && !swiperInstanceRef.current.destroyed) {
      swiperInstanceRef.current.slideNext();
    }
  };

  const renderGalerie = () => {
    return (
      <section
        className="swiper-games"
        style={{ marginBottom: 20, position: 'relative' }}
      >
        <components.BlockHeading
          className="container"
          title="Galerie"
          containerStyle={{ marginBottom: 14 }}
        />
        <div className="swiper-games__carousel">
          {!isBeginning && (
            <div
              ref={prevRef}
              className="swiper-nav-button prev"
              onClick={handlePrevSlide}
              style={{ cursor: 'pointer', zIndex: 10 }}
            >
              ❮
            </div>
          )}
          {!isEnd && (
            <div
              ref={nextRef}
              className="swiper-nav-button next"
              onClick={handleNextSlide}
              style={{ cursor: 'pointer', zIndex: 10 }}
            >
              ❯
            </div>
          )}

          <Swiper
            modules={[Navigation]}
            spaceBetween={14}
            mousewheel={true}
            navigation={false} // Désactiver la navigation automatique au début
            slidesPerView={
              game?.isPortrait ? (isDesktop ? 5.1 : 2.1) : isDesktop ? 3.2 : 1.2
            }
            onSwiper={(swiper) => {
              swiperInstanceRef.current = swiper;

              // Configurer la navigation après l'initialisation
              setTimeout(() => {
                if (
                  !swiper.destroyed &&
                  prevRef.current &&
                  nextRef.current &&
                  typeof swiper.params.navigation === 'object' &&
                  swiper.params.navigation
                ) {
                  Object.assign(swiper.params.navigation, {
                    prevEl: prevRef.current,
                    nextEl: nextRef.current,
                  });
                  swiper.navigation.init();
                  swiper.navigation.update();
                }
              }, 0);
            }}
            onSlideChange={(swiper) => {
              setIsBeginning(swiper.isBeginning);
              setIsEnd(swiper.isEnd);
            }}
            className="swiper-games__swiper"
          >
            {game?.covers.map((cover) => (
              <SwiperSlide key={cover.id}>
                <Image
                  src={`${URLS_ASSETS.GAMES}/${cover.imageUrl}`}
                  alt={game.title}
                  fill={false}
                  sizes="100vw"
                  priority
                  style={{
                    width: '100%',
                    height: 'auto',
                    borderRadius: 20,
                    marginBottom: 12,
                    objectFit: 'contain',
                  }}
                  width={0}
                  height={0}
                />
              </SwiperSlide>
            ))}
          </Swiper>
        </div>
      </section>
    );
  };

  const renderHeader = () => {
    return (
      <components.Header
        title={game?.title || ''}
        showGoBack={true}
        showBasket={true}
      />
    );
  };

  const renderBoxHeaderDesktop = () => {
    return (
      <section
        style={{ marginBottom: 20, position: 'relative', width: '100%' }}
      >
        <Box
          component="div"
          className="container-xl"
          sx={{
            height: isDesktop ? '70vh' : '37vh',
            position: 'relative',
            overflow: 'hidden',
          }}
        >
          {game && (game.videoCover || game.covers.length > 0) && (
            <Box
              component="div"
              sx={{
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                overflow: 'hidden',
              }}
            >
              {game.videoCover ? (
                <YouTubePlayer
                  videoId={(game.videoCover.split('v=')[1] as string) || ''}
                  loop={true}
                  autoPlay={true}
                  muted={true}
                  sx={{
                    width: '100%',
                    height: isDesktop ? '70vh' : '37vh',
                    borderRadius: 0,
                  }}
                />
              ) : (
                <Image
                  src={`${URLS_ASSETS.GAMES}/${game.covers[0].imageUrl}`}
                  alt={game.title}
                  fill
                  sizes="100vw"
                  priority
                  style={{ objectFit: 'cover' }}
                />
              )}

              {/* Overlay qui bloque les interactions */}
              <Box
                component="div"
                sx={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  background:
                    'linear-gradient(to bottom, rgba(0, 0, 0, 0.45) 0%, rgba(0, 0, 0, 0.8) 100%)',
                  zIndex: 10,
                  cursor: 'default',
                }}
              >
                <Stack
                  direction="column"
                  className="swiper-games"
                  justifyContent="flex-end"
                  alignItems="flex-start"
                  sx={{
                    position: 'relative',
                    zIndex: 20,
                    width: '100%',
                    height: '100%',
                  }}
                >
                  <Box
                    component="div"
                    sx={{
                      padding: 2,
                      marginBottom: 2,
                      marginLeft: 2,
                      marginRight: 2,
                      width: 'fit-content',
                    }}
                  >
                    <Image
                      src={`${URLS_ASSETS.GAMES}/${game.profilPicture}`}
                      alt={game.title}
                      width={isDesktop ? 200 : 100}
                      height={isDesktop ? 200 : 100}
                      priority={true}
                      style={{
                        // objectFit: 'contain',
                        borderRadius: 20,
                        marginBottom: 12,
                      }}
                    />
                    {isDesktop ? (
                      <h1 className="text-primary">{game?.title}</h1>
                    ) : (
                      <h3 className="text-primary">{game?.title}</h3>
                    )}
                    {isDesktop && (
                      <p
                        className="t16"
                        style={{
                          color: 'var(--white-color)',
                          marginTop: 2,
                          marginRight: 300,
                          fontFamily: 'var(--font-league-spartan)',
                        }}
                      >
                        {game?.description?.split('.').slice(0, 3).join('.') ||
                          ''}
                      </p>
                    )}
                    {renderPlayButtons()}
                  </Box>
                </Stack>
              </Box>
            </Box>
          )}
        </Box>
      </section>
    );
  };

  const renderHeaderDescriptionWithButtonLike = () => {
    return (
      <section
        className="container"
        style={{
          display: 'flex',
          flexDirection: 'row',
          alignItems: 'center',
          marginBottom: 2,
          justifyContent: 'space-between',
        }}
      >
        <h3>Description</h3>
        <button
          title="Add to wishlist"
          aria-label="Add to wishlist"
          style={{
            borderRadius: '50%',
          }}
          onClick={() => {
            // if (ifInWishlist) {
            //   if (product) {
            //     removeFromWishlist(product);
            //     return;
            //   }
            // } else {
            //   if (product) {
            //     addToWishlist(product);
            //     return;
            //   }
            // }
          }}
        >
          <svg.HeartSvg />
        </button>
      </section>
    );
  };

  const renderRatingWithInStock = () => {
    return (
      <section
        className="container"
        style={{
          gap: 8,
          display: 'flex',
          flexDirection: 'row',
          alignItems: 'center',
          marginBottom: 3,
        }}
      >
        {/* Rating */}
        {game && game.ratings.length > 0 && (
          <div
            style={{
              paddingLeft: 5,
              paddingRight: 5,
              borderRadius: 30,
              display: 'flex',
              gap: 4,
              alignItems: 'center',
              flexDirection: 'row',
              paddingTop: 2,
              paddingBottom: 2,
              backgroundColor: 'var(--white-color)',
            }}
          >
            <svg.StarSvg />
            <span
              style={{
                fontSize: 12,
                lineHeight: 1.2,
                color: 'var(--text-color)',
                marginTop: 2,
                fontFamily: 'var(--font-league-spartan)',
              }}
            >
              {game.ratings.reduce((acc, item) => acc + item.value, 0) /
                game.ratings.length}
            </span>
          </div>
        )}
      </section>
    );
  };

  const renderDescription = () => {
    return (
      <Box className="container" sx={{ marginTop: 4 }}>
        <div style={{ paddingBottom: 13, borderBottom: '1px solid #C8CDD9' }}>
          <p
            className="t16"
            style={{ marginBottom: 16, whiteSpace: 'pre-line' }}
          >
            {game?.description}
          </p>
        </div>
      </Box>
    );
  };

  const renderRankingMobile = () => {
    if (ranking.allRanking.length === 0) {
      return <NoGammers />;
    }

    return (
      <Box component="div" sx={{ padding: 0, margin: 0 }}>
        <Box
          component="div"
          sx={{
            position: 'relative',
            backgroundImage: 'url(/assets/bg/podium.jpg)',
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            width: '100%',
            minHeight: 300,
            margin: 0,
            padding: 0,
          }}
        >
          <Box
            component="div"
            sx={{
              position: 'absolute',
              top: 55,
              left: ranking.allRanking[0].pseudo.length > 10 ? '36%' : '40%',
              textAlign: 'center',
            }}
          >
            <Badge
              count={ranking.allRanking[0].rank}
              offset={[-10, 10]}
              color="var(--accent-color)"
            >
              <Avatar
                size={{ xs: 80, sm: 145 }}
                src={`${URLS_ASSETS.AVATARS}/${ranking.allRanking[0].profil}`}
              />
            </Badge>
            <h4 className="text-black t18" style={{ marginBottom: 0 }}>
              {ranking.allRanking[0].pseudo}
            </h4>
            <p className="t14 text-white" style={{ marginBottom: 16 }}>
              {ranking.allRanking[0].highScore} Pts
            </p>
          </Box>

          {ranking.allRanking[1] && (
            <Box
              component="div"
              sx={{
                position: 'absolute',
                top: 90,
                right: ranking.allRanking[1].pseudo.length > 10 ? '4%' : '7%',
                textAlign: 'center',
              }}
            >
              <Badge
                count={ranking.allRanking[1].rank}
                offset={[-10, 10]}
                color="var(--accent-color)"
              >
                <Avatar
                  size={{ xs: 80, sm: 145 }}
                  src={`${URLS_ASSETS.AVATARS}/${ranking.allRanking[1].profil}`}
                />
              </Badge>
              <h4 className="text-black t18" style={{ marginBottom: 0 }}>
                {ranking.allRanking[1].pseudo}
              </h4>
              <p className="t14 text-white" style={{ marginBottom: 16 }}>
                {ranking.allRanking[1].highScore} Pts
              </p>
            </Box>
          )}
          {ranking.allRanking[2] && (
            <Box
              component="div"
              sx={{
                position: 'absolute',
                top: 90,
                left: ranking.allRanking[2].pseudo.length > 10 ? '4%' : '7%',
                textAlign: 'center',
              }}
            >
              <Badge
                count={ranking.allRanking[2].rank}
                offset={[-10, 10]}
                color="var(--accent-color)"
              >
                <Avatar
                  size={{ xs: 80, sm: 145 }}
                  src={`${URLS_ASSETS.AVATARS}/${ranking.allRanking[2].profil}`}
                />
              </Badge>
              <h4
                className="text-black t18"
                style={{ marginBottom: 0, paddingBottom: 0 }}
              >
                {ranking.allRanking[2].pseudo}
              </h4>
              <p
                className="t14 text-white"
                style={{ marginBottom: 16, marginTop: 0 }}
              >
                {ranking.allRanking[2].highScore} Pts
              </p>
            </Box>
          )}
        </Box>
        {ranking.allRanking.length > 3 && (
          <Box
            component="div"
            sx={{
              margin: 0,
              backgroundColor: '#573005',
              minHeight: 300,
              width: '100%',
            }}
          ></Box>
        )}
      </Box>
    );
  };

  const renderRankingDesktop = () => {
    if (ranking.allRanking.length === 0) {
      return <NoGammers />;
    }

    return (
      <Box component="div" sx={{ padding: 0, margin: 0 }}>
        <Box
          component="div"
          sx={{
            position: 'relative',
            backgroundImage: 'url(/assets/bg/podium.jpg)',
            backgroundSize: 'cover',
            backgroundRepeat: 'no-repeat',
            backgroundPosition: 'bottom',
            width: '100%',
            minHeight: 400,
            margin: 0,
            padding: 0,
          }}
        >
          <Box
            component="div"
            sx={{
              position: 'absolute',
              top: 75,
              left: ranking.allRanking[0].pseudo.length > 10 ? '40%' : '40%',
              textAlign: 'center',
            }}
          >
            <Badge
              count={ranking.allRanking[0].rank}
              offset={[-10, 10]}
              color="var(--accent-color)"
            >
              <Avatar
                size={100}
                src={`${URLS_ASSETS.AVATARS}/${ranking.allRanking[0].profil}`}
              />
            </Badge>
            <h4 className="text-black t18" style={{ marginBottom: 0 }}>
              {ranking.allRanking[0].pseudo}
            </h4>
            <p className="t14 text-white" style={{ marginBottom: 16 }}>
              {ranking.allRanking[0].highScore} Pts
            </p>
          </Box>

          {ranking.allRanking[1] && (
            <Box
              component="div"
              sx={{
                position: 'absolute',
                top: 90,
                right: ranking.allRanking[1].pseudo.length > 10 ? '4%' : '7%',
                textAlign: 'center',
              }}
            >
              <Badge
                count={ranking.allRanking[1].rank}
                offset={[-10, 10]}
                color="var(--accent-color)"
              >
                <Avatar
                  size={{ xs: 80, sm: 145 }}
                  src={`${URLS_ASSETS.AVATARS}/${ranking.allRanking[1].profil}`}
                />
              </Badge>
              <h4 className="text-black t18" style={{ marginBottom: 0 }}>
                {ranking.allRanking[1].pseudo}
              </h4>
              <p className="t14 text-white" style={{ marginBottom: 16 }}>
                {ranking.allRanking[1].highScore} Pts
              </p>
            </Box>
          )}
          {ranking.allRanking[2] && (
            <Box
              component="div"
              sx={{
                position: 'absolute',
                top: 90,
                left: ranking.allRanking[2].pseudo.length > 10 ? '4%' : '7%',
                textAlign: 'center',
              }}
            >
              <Badge
                count={ranking.allRanking[2].rank}
                offset={[-10, 10]}
                color="var(--accent-color)"
              >
                <Avatar
                  size={{ xs: 80, sm: 145 }}
                  src={`${URLS_ASSETS.AVATARS}/${ranking.allRanking[2].profil}`}
                />
              </Badge>
              <h4
                className="text-black t18"
                style={{ marginBottom: 0, paddingBottom: 0 }}
              >
                {ranking.allRanking[2].pseudo}
              </h4>
              <p
                className="t14 text-white"
                style={{ marginBottom: 16, marginTop: 0 }}
              >
                {ranking.allRanking[2].highScore} Pts
              </p>
            </Box>
          )}
        </Box>
        {ranking.allRanking.length > 3 && (
          <Box
            component="div"
            sx={{
              margin: 0,
              backgroundColor: '#573005',
              minHeight: 300,
              width: '100%',
            }}
          ></Box>
        )}
      </Box>
    );
  };

  const renderReviews = () => {
    return (
      <Box component={'div'} className="container" sx={{ marginTop: 4 }}>
        <components.BlockHeading
          // href={Routes.REVIEWS}
          title={`Avis (${reviews.length})`}
          containerStyle={{ marginBottom: 24 }}
        />
        <ul>
          {reviews.map((review, index) => {
            const isLast = index === reviews.length - 1;

            return (
              <items.ReviewItem
                key={review.id}
                review={review}
                isLast={isLast}
              />
            );
          })}
        </ul>
        {/* {renderButtons()} */}
      </Box>
    );
  };

  const renderButtons = () => {
    return (
      <Box className="container" sx={{ marginBottom: 10 }}>
        <components.Button
          label="Ajouter un avis"
          onClick={() => {
            if (game) {
              // addToCart(product);
            }
          }}
          containerStyle={{ marginBottom: 16 }}
        />
      </Box>
    );
  };

  const renderPlayButtons = () => {
    return (
      <Box
        component="div"
        sx={{
          width: '20%',
          minWidth: 200,
          marginTop: 2,
        }}
      >
        <Button
          label="Jouer maintenant"
          aria-label="Play now"
          containerStyle={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'flex-end',
            flexDirection: 'row',
            width: '100%',
          }}
          style={{ padding: 0, margin: 0 }}
          onClick={(e) => {
            e.stopPropagation();
            e.preventDefault();
            const url = `${Routes.GAME_PLAY}/${game!.title.replaceAll(' ', '_')}/${game!.id}`;
            if (user && hasActiveSubscription(user.subscriptions)) {
              router.push(url);
              return;
            }
            LocalStorageService.saveLocationRedirection(url);
            openModalSubscribe();
          }}
        />
      </Box>
    );
  };

  const renderTabsHeader = () => (
    <Tabs
      sx={{ marginBottom: 0 }}
      value={activeTab}
      onChange={handleChange}
      centered
    >
      <Tab
        icon={
          <MilitaryTechTwoToneIcon
            sx={{
              color: activeTab === 0 ? activeColor : inactiveColor,
              opacity: activeTab === 0 ? 1 : 0.7,
            }}
          />
        }
        iconPosition="start"
        label="Records"
      />
      <Tab
        icon={
          <ReviewsTwoToneIcon
            sx={{
              color: activeTab === 1 ? activeColor : inactiveColor,
              opacity: activeTab === 1 ? 1 : 0.7,
            }}
          />
        }
        iconPosition="start"
        label="Avis"
      />
    </Tabs>
  );

  const renderModal = () => {
    return <components.Modal />;
  };
  const renderModalSubscribe = () => {
    return <components.ModalSubscribe />;
  };

  const renderContent = () => {
    return (
      <main
        className="scrollable"
        style={{ paddingTop: 10, paddingBottom: 20, width: '100%' }}
      >
        {renderBoxHeaderDesktop()}
        {renderGalerie()}
        {renderHeaderDescriptionWithButtonLike()}
        {renderDescription()}
        {renderRatingWithInStock()}
        {renderTabsHeader()}
        {activeTab === 0 && !isDesktop && renderRankingMobile()}
        {activeTab === 0 && isDesktop && renderRankingDesktop()}
        {activeTab === 1 && renderReviews()}
      </main>
    );
  };

  const handleChange = (event: React.SyntheticEvent, newValue: number) => {
    setActiveTab(newValue);
  };

  const renderBackground = () => {
    return <components.Background />;
  };

  if (isLoading) {
    return (
      <components.Screen>
        {renderBackground()}
        {renderHeader()}
        <Box
          component="div"
          sx={{
            width: '100%',
            height: '100%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          <CircularProgress />
        </Box>
      </components.Screen>
    );
  }

  return (
    <components.Screen>
      {renderBackground()}
      {renderHeader()}
      {renderContent()}
      {renderModal()}
      {renderModalSubscribe()}
    </components.Screen>
  );
};
