import { Box, SxProps, Theme } from '@mui/material';
import React, { useState, useEffect, useRef } from 'react';
import YouTube from 'react-youtube';

interface YouTubePlayerProps {
  videoId: string;
  autoPlay?: boolean;
  muted?: boolean;
  loop?: boolean;
  className?: string;
  sx?: SxProps<Theme> | undefined;
}

const YouTubePlayer = ({
  videoId,
  autoPlay = false,
  muted = true,
  loop = false,
  className = '',
  sx,
}: YouTubePlayerProps) => {
  const [player, setPlayer] = useState<any>(null);
  const [userInteracted, setUserInteracted] = useState(false);
  const hasAttemptedAutoplay = useRef(false);
  const containerRef = useRef<HTMLDivElement>(null);

  // Détection iOS/mobile
  const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
  const isMobile =
    /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(
      navigator.userAgent,
    );

  const opts = {
    height: '100%',
    width: '100%',
    playerVars: {
      autoplay: autoPlay ? 1 : 0,
      mute: muted ? 1 : 0,
      modestbranding: 1,
      rel: 0,
      controls: 0,
      disablekb: 1,
      fs: 0,
      playsinline: 1, // Crucial pour iOS
      loop: loop ? 1 : 0,
      playlist: loop ? videoId : undefined,
      // Paramètres spécifiques pour mobile
      ...(isMobile && {
        iv_load_policy: 3,
        cc_load_policy: 0,
        showinfo: 0,
      }),
    },
  };

  const handleEnd = () => {
    if (loop && player) {
      player.seekTo(0);
      player.playVideo();
    }
  };

  const attemptAutoplay = async (playerInstance: any) => {
    if (!autoPlay || hasAttemptedAutoplay.current || !playerInstance) return;
    hasAttemptedAutoplay.current = true;

    try {
      // Vérifier que le player est toujours valide
      if (typeof playerInstance.playVideo !== 'function') {
        console.warn('Player instance is not valid');
        return;
      }

      // Force mute d'abord sur mobile
      if (isMobile || isIOS) {
        await playerInstance.mute();
        // Petit délai pour s'assurer que le mute est effectif
        setTimeout(() => {
          if (
            playerInstance &&
            typeof playerInstance.playVideo === 'function'
          ) {
            playerInstance.playVideo().catch((error: any) => {
              console.warn('Autoplay failed on mobile:', error);
            });
          }
        }, 100);
      } else {
        await playerInstance.playVideo();
      }
    } catch (error) {
      console.warn('Autoplay failed:', error);
      // Fallback: s'assurer que la vidéo est mutée et réessayer
      if (playerInstance && typeof playerInstance.mute === 'function') {
        playerInstance.mute();
        setTimeout(() => {
          if (
            playerInstance &&
            typeof playerInstance.playVideo === 'function'
          ) {
            playerInstance.playVideo().catch(() => {
              console.warn(
                'Autoplay definitively failed - user interaction required',
              );
            });
          }
        }, 200);
      }
    }
  };

  const onReady = (event: any) => {
    setPlayer(event.target);

    // Sur iOS/mobile, attendre un peu avant de tenter l'autoplay
    if (isIOS || isMobile) {
      setTimeout(() => attemptAutoplay(event.target), 500);
    } else {
      attemptAutoplay(event.target);
    }
  };

  // Gestion du clic/touch pour démarrer la vidéo sur mobile
  const handleContainerInteraction = () => {
    if (
      !userInteracted &&
      player &&
      typeof player.playVideo === 'function' &&
      (isIOS || isMobile)
    ) {
      try {
        setUserInteracted(true);
        player.mute();
        setTimeout(() => {
          // Double vérification avant de jouer
          if (player && typeof player.playVideo === 'function') {
            player.playVideo().catch((error: any) => {
              console.warn('Play after interaction failed:', error);
            });
          }
        }, 100);
      } catch (error) {
        console.warn('Container interaction failed:', error);
      }
    }
  };

  useEffect(() => {
    if (player && typeof player.loadVideoById === 'function') {
      try {
        player.loadVideoById(videoId);
        hasAttemptedAutoplay.current = false;

        // Réessayer l'autoplay après le changement de vidéo
        if (autoPlay) {
          setTimeout(() => {
            // Vérifier à nouveau que le player existe avant l'autoplay
            if (player && typeof player.playVideo === 'function') {
              attemptAutoplay(player);
            }
          }, 300);
        }
      } catch (error) {
        console.warn('Failed to load video:', error);
      }
    }
  }, [videoId, player]);

  // Écouter les événements d'interaction sur mobile
  useEffect(() => {
    const container = containerRef.current;
    if (!container || (!isIOS && !isMobile)) return;

    const handleTouch = () => handleContainerInteraction();
    const handleClick = () => handleContainerInteraction();

    container.addEventListener('touchstart', handleTouch, { passive: true });
    container.addEventListener('click', handleClick);

    return () => {
      container.removeEventListener('touchstart', handleTouch);
      container.removeEventListener('click', handleClick);
    };
  }, [player, userInteracted, isIOS, isMobile]);

  return (
    <Box
      ref={containerRef}
      sx={{
        borderRadius: '20px',
        overflow: 'hidden',
        position: 'relative',
        width: '100%',
        height: '100%',
        cursor: (isIOS || isMobile) && !userInteracted ? 'pointer' : 'default',
        ...sx,
      }}
      className={className}
    >
      <Box
        sx={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          '& iframe': {
            position: 'absolute',
            top: '50%',
            left: '50%',
            width: '177.77vh',
            height: '56.25vw',
            minWidth: '100%',
            minHeight: '100%',
            transform: 'translate(-50%, -50%)',
          },
        }}
      >
        <YouTube
          videoId={videoId}
          opts={opts}
          onReady={onReady}
          onEnd={handleEnd}
        />
      </Box>

      {/* Overlay transparent pour capturer les interactions sur mobile */}
      {(isIOS || isMobile) && !userInteracted && (
        <Box
          sx={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            backgroundColor: 'transparent',
            zIndex: 1,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
          onClick={handleContainerInteraction}
        >
          {/* Optionnel: icône play pour indiquer à l'utilisateur qu'il peut cliquer */}
          {/* <Box
            sx={{
              width: 60,
              height: 60,
              borderRadius: '50%',
              backgroundColor: 'rgba(0,0,0,0.6)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: 'white',
              fontSize: '24px',
              opacity: 0.8,
            }}
          >
            ▶
          </Box> */}
        </Box>
      )}
    </Box>
  );
};

export default YouTubePlayer;
