// hooks/useGamePreload.ts

import React, { useEffect, useMemo, useRef } from 'react';
import type { Game } from '../types';
import { GamePreloadService } from '@/services/GamePreloadService';

/**
 * Options pour le hook de préchargement
 */
interface UseGamePreloadOptions {
  enabled?: boolean;
  enableHover?: boolean;
  enableVisibility?: boolean;
  hoverDelay?: number;
  visibilityThreshold?: number;
  visibilityRootMargin?: string;
}

/**
 * Hook pour précharger un jeu individuel
 */
export const useGamePreload = (
  game: Game,
  containerRef: React.RefObject<HTMLElement | null>,
  options: UseGamePreloadOptions = {},
) => {
  const {
    enabled = true,
    enableHover = true,
    enableVisibility = true,
    hoverDelay = 200,
    visibilityThreshold = 0.3,
    visibilityRootMargin = '100px',
  } = options;

  const hasPreloaded = useRef(false);
  const hoverTimeout = useRef<NodeJS.Timeout | null>(null);

  // Préchargement au survol
  const handleMouseEnter = () => {
    if (!enabled || !enableHover || !game.url || hasPreloaded.current) return;

    hoverTimeout.current = setTimeout(() => {
      hasPreloaded.current = true;
      // console.log(`🖱️ Hover détecté, préchargement: ${game.title}`);
      GamePreloadService.preloadGame(game.url!, game.id);
    }, hoverDelay);
  };

  const handleMouseLeave = () => {
    if (hoverTimeout.current) {
      clearTimeout(hoverTimeout.current);
    }
  };

  // Préchargement basé sur la visibilité
  useEffect(() => {
    if (!enabled || !enableVisibility || !game.url) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (
            entry.isIntersecting &&
            entry.intersectionRatio > visibilityThreshold
          ) {
            if (!hasPreloaded.current) {
              hasPreloaded.current = true;
              // const visibilityPercent = Math.round(entry.intersectionRatio * 100);
              // console.log(`👁️ Visible (${visibilityPercent}%), préchargement: ${game.title}`);

              // Délai progressif basé sur la visibilité
              const delay = entry.intersectionRatio < 0.5 ? 500 : 100;
              setTimeout(() => {
                GamePreloadService.preloadGame(game.url!, game.id);
              }, delay);
            }
          }
        });
      },
      {
        threshold: [visibilityThreshold, 0.5, 1.0],
        rootMargin: visibilityRootMargin,
      },
    );

    if (containerRef.current) {
      observer.observe(containerRef.current);
    }

    return () => {
      if (containerRef.current) {
        observer.unobserve(containerRef.current);
      }
      if (hoverTimeout.current) {
        clearTimeout(hoverTimeout.current);
      }
    };
  }, [
    game.url,
    game.id,
    game.title,
    enabled,
    enableVisibility,
    visibilityThreshold,
    visibilityRootMargin,
  ]);

  return {
    handleMouseEnter,
    handleMouseLeave,
    isPreloaded: GamePreloadService.isPreloaded(game.id),
    status: GamePreloadService.getStatus(game.id),
  };
};

/**
 * Hook pour précharger plusieurs jeux (liste ou grille)
 */
export const useGameListPreload = (
  games: Game[],
  maxToPreload = 10,
  options: { enabled?: boolean; delayBetween?: number } = {},
) => {
  const { enabled = true, delayBetween = 800 } = options;

  // 🔥 CRITIQUE : Mémoriser les IDs pour éviter les re-renders
  const gameIds = useMemo(
    () =>
      games
        .slice(0, maxToPreload)
        .map((g) => g.id)
        .join(','),
    [games, maxToPreload],
  );

  useEffect(() => {
    if (!enabled) return;

    const gamesToPreload = games.slice(0, maxToPreload).filter((g) => g.url);

    // ⚠️ Protection contre les appels multiples
    if (gamesToPreload.length === 0) {
      console.log('⏭️ Aucun jeu à précharger, skip');
      return;
    }

    console.log(
      `📋 Préchargement de ${gamesToPreload.length} jeux:`,
      gamesToPreload.map((g) => g.title),
    );

    // Préchargement échelonné
    const timeouts: NodeJS.Timeout[] = [];

    gamesToPreload.forEach((game, index) => {
      const timeout = setTimeout(() => {
        console.log(
          `⏱️ [${index + 1}/${gamesToPreload.length}] Préchargement: ${game.title}`,
        );
        GamePreloadService.preloadGame(game.url!, game.id);
      }, index * delayBetween);

      timeouts.push(timeout);
    });

    // 🧹 Cleanup : annuler tous les timeouts
    return () => {
      console.log('🧹 Cleanup des timeouts de préchargement');
      timeouts.forEach((timeout) => clearTimeout(timeout));
    };
  }, [gameIds, enabled, delayBetween]); // ⚠️ Utiliser gameIds au lieu de games

  return {
    stats: GamePreloadService.getStats(),
  };
};

/**
 * Hook pour obtenir le statut de préchargement d'un jeu
 */
export const useGamePreloadStatus = (gameId: string) => {
  const [status, setStatus] = React.useState(() =>
    GamePreloadService.getStatus(gameId),
  );

  useEffect(() => {
    // Vérifier le statut périodiquement
    const interval = setInterval(() => {
      const newStatus = GamePreloadService.getStatus(gameId);
      if (newStatus !== status) {
        setStatus(newStatus);
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [gameId, status]);

  return {
    status,
    isPreloaded: status === 'loaded',
    isLoading: status === 'loading',
    hasError: status === 'error',
  };
};

