import { servicesMobileMoney } from '@/constants/serviceMobileMoney';

export function getServiceFromSubdomain(): string | null {
  if (typeof window === 'undefined') {
    return null;
  }
  const labels = window.location.hostname.split('.');
  if (labels.length < 3) {
    return null;
  }
  const subdomain = labels[0].toLowerCase();
  const known = servicesMobileMoney.some(
    (service) => service.name === subdomain,
  );
  return known ? subdomain : null;
}
