'use client';
import { data } from '@/data';
import {
  getGameByIdIndexDb,
  saveAllGamesIndexDb,
  saveCategoriesBlocGameIndexDb,
} from '@/storages/indexed_db_service';
import { Game } from '@/types/GameType';
import { getUniqueGames } from '@/utils/game_helper';
import { useEffect, useState } from 'react';
import { GameContent } from './GameContent';
import { stores } from '@/stores';

type Props = {
  id: string;
};

export const DetailGamePageClient: React.FC<Props> = ({ id }) => {
  const [game, setGame] = useState<Game | null>(null);
  const [ranking, setRanking] = useState<{
    myRank: RankingType | null;
    allRanking: RankingType[];
  }>({ myRank: null, allRanking: [] });
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const { setPricings } = stores.usePricingStore();

  useEffect(() => {
    let isMounted = true;

    const loadData = async () => {
      try {
        setIsLoading(true);
        setError(null);

        // 1. Charger d'abord depuis IndexDB pour affichage rapide
        try {
          const gamesFromDB = await getGameByIdIndexDb(id);
          if (isMounted && gamesFromDB) {
            setGame(gamesFromDB);
          }
        } catch (dbError) {
          console.error('Erreur IndexDB:', dbError);
          // Continue même si IndexDB échoue
        }

        // 2. Charger depuis l'API pour mise à jour
        const [gamesData, gameData, pricingData] = await Promise.all([
          data.getGames().catch((err) => {
            console.error('Erreur getGames:', err);
            return [];
          }),
          data.getGamesByID(id).catch((err) => {
            console.error('Erreur getGamesByID:', err);
            return null;
          }),
          data.getPricing().catch((err) => {
            console.error('Erreur getPricing:', err);
            return [];
          }),
        ]);

        if (!isMounted) return;

        // Traiter les jeux
        if (gamesData && gamesData.length > 0) {
          const allGames = gamesData
            .map((gameWithCategorie) => gameWithCategorie.games)
            .flat();
          const allGameFilter = getUniqueGames(allGames) as Game[];
          const gameInfo = allGameFilter.find((game) => game.id === id);

          if (gameInfo) {
            setGame(gameInfo);
          }

          // Sauvegarder en arrière-plan
          saveAllGamesIndexDb(allGameFilter).catch((err) =>
            console.error('Erreur sauvegarde games:', err),
          );
          saveCategoriesBlocGameIndexDb(gamesData).catch((err) =>
            console.error('Erreur sauvegarde categories:', err),
          );
        }

        // Traiter les prix
        if (pricingData && pricingData.length > 0) {
          const pricings = pricingData.sort((a, b) => a.price - b.price);
          setPricings(pricings);
        }

        // Traiter le ranking
        if (gameData?.ranking) {
          setRanking(gameData.ranking);
        }
      } catch (error) {
        console.error('Erreur critique lors du chargement:', error);
        if (isMounted) {
          setError('Erreur lors du chargement du jeu');
        }
      } finally {
        if (isMounted) {
          setIsLoading(false);
        }
      }
    };

    loadData();

    return () => {
      isMounted = false;
    };
  }, [id, setPricings]);

  if (error) {
    return (
      <div style={{ padding: 20, textAlign: 'center' }}>
        <h3>Erreur</h3>
        <p>{error}</p>
      </div>
    );
  }

  return (
    <GameContent
      game={game}
      reviews={[]}
      ranking={ranking}
      isLoading={isLoading}
    />
  );
};
